#include <stdio.h>

int main() {
  int fahr;

  printf("Fahrenheit  Celsius  using 5 / 9\n");
  for (fahr = 0; fahr <= 100; fahr += 20) {
    double celsius = (5.0 / 9.0) * (fahr - 32);   /* 5.0 has a decimal point, so this works */
    int broken = 5 / 9 * (fahr - 32);              /* 5 / 9 is 0 in whole numbers, so this is always 0 */
    printf("%10d %8.1f %8d\n", fahr, celsius, broken);
  }

  /* Every C type has a fixed size, counted in bytes (8 bits each). */
  printf("\nA char is %d byte\n", (int)sizeof(char));
  printf("An int is %d bytes\n", (int)sizeof(int));
  printf("A double is %d bytes\n", (int)sizeof(double));
  return 0;
}

#include <stdio.h>

/* Each topping gets its own bit. */
#define CHEESE    1   /* 0001 */
#define TOMATO    2   /* 0010 */
#define MUSHROOM  4   /* 0100 */
#define PINEAPPLE 8   /* 1000 */

void show(const char *step, int order) {
  int bit;
  printf("%-22s ", step);
  for (bit = 3; bit >= 0; bit--) printf("%d", (order >> bit) & 1);   /* >> moves a bit to the end */
  printf(" = %2d   pineapple:%s\n", order, (order & PINEAPPLE) ? "yes" : "no");
}

int main() {
  int order = CHEESE | TOMATO;          /* |  switches bits on  */
  show("cheese and tomato", order);
  order = order | PINEAPPLE;
  show("add pineapple", order);
  order = order & ~TOMATO;              /* & ~ switches one off */
  show("hold the tomato", order);
  order = order ^ MUSHROOM;             /* ^  flips a bit       */
  show("flip mushroom", order);
  return 0;
}

#include <stdio.h>
#include <string.h>
#include <nb.h>

#define WIDTH 63
#define STEPS 32

int main(void) {
  int rule = (int)nb_get_int("ca_choice", 30);   /* the slider above writes ca_choice */
  if (rule < 0 || rule > 255) rule = 30;

  int cells[WIDTH], next[WIDTH];
  static char json[STEPS * (WIDTH + 3) + 2];     /* the rows, as a JSON list of text */
  int len = 0;

  for (int i = 0; i < WIDTH; i++) cells[i] = 0;  /* C doesn't clear memory for you */
  cells[WIDTH / 2] = 1;

  json[len++] = '[';
  for (int step = 0; step < STEPS; step++) {
    if (step) json[len++] = ',';
    json[len++] = '"';
    for (int i = 0; i < WIDTH; i++) json[len++] = cells[i] ? '#' : '.';
    json[len++] = '"';

    for (int i = 0; i < WIDTH; i++) {
      int left = cells[(i + WIDTH - 1) % WIDTH];
      int right = cells[(i + 1) % WIDTH];
      int pattern = left * 4 + cells[i] * 2 + right;   /* three cells make a number 0 to 7 */
      next[i] = (rule >> pattern) & 1;                 /* that bit of the rule is the answer */
    }
    memcpy(cells, next, sizeof cells);
  }
  json[len++] = ']';
  json[len] = '\0';

  nb_set_int("ca_rule", rule);
  nb_set_json("ca_rows", json);
  printf("Rule %d: %d rows of %d cells shared as nb.ca_rows\n", rule, STEPS, WIDTH);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <nb.h>

#define CHEESE    1
#define TOMATO    2
#define MUSHROOM  4
#define PINEAPPLE 8

/* A struct groups related values into one type. */
struct Order {
  const char *name;
  int toppings;     /* bit flags, as in section 2 */
  double price;     /* worked out below */
};

int count_toppings(int flags) {
  int n = 0;
  for (; flags; flags >>= 1) n += flags & 1;
  return n;
}

/* qsort calls this to compare two orders: the most expensive first. */
int by_price(const void *a, const void *b) {
  const struct Order *x = a, *y = b;
  return (y->price > x->price) - (y->price < x->price);
}

int main(void) {
  struct Order orders[] = {
    { "Ada",      CHEESE | TOMATO,                         0 },
    { "Grace",    CHEESE | MUSHROOM | PINEAPPLE,           0 },
    { "Linus",    CHEESE,                                  0 },
    { "Margaret", CHEESE | TOMATO | MUSHROOM | PINEAPPLE,  0 },
  };
  int n = sizeof orders / sizeof orders[0];
  double total = 0;

  for (int i = 0; i < n; i++) {
    orders[i].price = 7.50 + 1.25 * count_toppings(orders[i].toppings);
    total += orders[i].price;
  }
  qsort(orders, n, sizeof orders[0], by_price);

  printf("%-10s %9s %8s\n", "Name", "Toppings", "Price");
  for (int i = 0; i < n; i++)
    printf("%-10s %9d %8.2f\n", orders[i].name, count_toppings(orders[i].toppings), orders[i].price);
  printf("%-10s %9s %8.2f\n", "Total", "", total);

  nb_set_number("pizza_total", total);
  return 0;
}
